}

const Href = (
    { url = '#', target = '_blank', rel = 'noopener noreferrer nofollow', children, ...rest }: Props,
    ref: Ref<HTMLAnchorElement>
) => (
    <a href={url} target={target} rel={rel} ref={ref} {...rest}>
        {children}
    </a>
);

